   772	// queryGitHubRunsForWorkflow queries recent runs for a specific workflow using gh CLI.
   773	// Returns runs sorted newest-first (GitHub API default).
   774	func queryGitHubRunsForWorkflow(workflow string, limit int) ([]GHWorkflowRun, error) {
   775		if _, err := exec.LookPath("gh"); err != nil {
   776			return nil, fmt.Errorf("gh CLI not found: install from https://cli.github.com")
   777		}
   778	
   779		args := []string{
   780			"run", "list",
   781			"--workflow", workflow,
   782			"--json", "databaseId,name,status,conclusion,createdAt,workflowName",
   783			"--limit", fmt.Sprintf("%d", limit),
   784		}
   785	
   786		cmd := exec.Command("gh", args...)
   787		output, err := cmd.Output()
   788		if err != nil {
   789			if exitErr, ok := err.(*exec.ExitError); ok {
   790				return nil, fmt.Errorf("gh run list --workflow=%s failed: %s", workflow, string(exitErr.Stderr))
   791			}
   792			return nil, fmt.Errorf("gh run list: %w", err)
   793		}
   794	
   795		var runs []GHWorkflowRun
   796		if err := json.Unmarshal(output, &runs); err != nil {
   797			return nil, fmt.Errorf("parse gh output: %w", err)
   798		}
   799	
   800		return runs, nil
   801	}
