   803	// discoverRunIDByWorkflowName queries GitHub for the most recent run of a workflow.
   804	// Returns (runID, error). This is ZFC-compliant: "most recent run" is deterministic.
   805	func discoverRunIDByWorkflowName(workflowHint string) (string, error) {
   806		// Query GitHub directly for this workflow (efficient, avoids limit issues)
   807		runs, err := queryGitHubRunsForWorkflow(workflowHint, 5)
   808		if err != nil {
   809			return "", fmt.Errorf("failed to query workflow runs: %w", err)
   810		}
   811	
   812		if len(runs) == 0 {
   813			return "", fmt.Errorf("no runs found for workflow '%s'", workflowHint)
   814		}
   815	
   816		// Take the most recent run (gh returns newest-first)
   817		// This is deterministic: "most recent" is a total ordering by creation time
   818		return fmt.Sprintf("%d", runs[0].DatabaseID), nil
   819	}
