   938	// checkTimer checks a timer gate for expiration
   939	// Note: timers resolve but never escalate (escalated is always false by design)
   940	func checkTimer(gate *types.Issue, now time.Time) (resolved, escalated bool, reason string, err error) { //nolint:unparam // escalated intentionally always false
   941		if gate.Timeout == 0 {
   942			return false, false, "timer gate without timeout configured", fmt.Errorf("no timeout set")
   943		}
   944	
   945		expiresAt := gate.CreatedAt.Add(gate.Timeout)
   946		if now.After(expiresAt) {
   947			expired := now.Sub(expiresAt).Round(time.Second)
   948			return true, false, fmt.Sprintf("timer expired %s ago", expired), nil
   949		}
   950	
   951		remaining := expiresAt.Sub(now).Round(time.Second)
   952		return false, false, fmt.Sprintf("expires in %s", remaining), nil
   953	}
